{
  "vision": "Enable seamless migration of customer profile data from PostgreSQL to MongoDB to support flexible, country-specific schemas required for global expansion while ensuring zero downtime, data integrity, and backward-compatible APIs.",
  "scope": "Migrate ~2M customer records (150GB) from PostgreSQL to MongoDB using CDC for backfill. Implement dual-write mechanism for a 2-week transitional period. Ensure zero data loss, stable API responses, and read latency under 50ms. Boundaries include database migration, schema adaptation, and infrastructure configuration without altering business logic or UI elements.",
  "success_criteria": [
    "100% of customer records successfully migrated and validated for parity",
    "API remains backward-compatible throughout migration with zero downtime"
  ],
  "user_stories": [
    {
      "id": "US-001",
      "title": "Design MongoDB schema to accommodate country-specific fields for flexible international data storage",
      "as_a": "data architect",
      "i_want": "to design a document-based MongoDB schema for customer profiles",
      "so_that": "new country-specific fields can be added without schema migrations or release delays",
      "acceptance_criteria": [
        {"given": "existing PostgreSQL schema with fixed columns", "when": "MongoDB schema is defined", "then": "each document structure supports country-specific subfields without affecting existing data"}
      ],
      "priority": "High",
      "story_points": 5,
      "labels": ["schema", "mongodb", "data-flexibility"]
    },
    {
      "id": "US-002",
      "title": "Implement CDC-based backfill process from PostgreSQL to MongoDB for customer profile data",
      "as_a": "data engineer",
      "i_want": "to configure CDC to stream changes from PostgreSQL to MongoDB",
      "so_that": "data remains synchronized during migration and no records are lost",
      "acceptance_criteria": [
        {"given": "existing PostgreSQL tables and target MongoDB collections", "when": "CDC pipeline is executed", "then": "all changes are captured and reflected accurately with zero data loss"}
      ],
      "priority": "High",
      "story_points": 8,
      "labels": ["cdc", "migration", "data-integrity"]
    },
    {
      "id": "US-003",
      "title": "Enable dual-write mechanism between PostgreSQL and MongoDB during the migration period",
      "as_a": "backend engineer",
      "i_want": "to write customer profile updates to both PostgreSQL and MongoDB",
      "so_that": "data consistency is maintained across systems during phased migration",
      "acceptance_criteria": [
        {"given": "an API writing customer data", "when": "a write operation occurs during dual-write period", "then": "both databases are updated successfully and logs confirm consistency"}
      ],
      "priority": "High",
      "story_points": 8,
      "labels": ["dual-write", "backend", "consistency"]
    },
    {
      "id": "US-004",
      "title": "Validate record parity between PostgreSQL and MongoDB before final cutover",
      "as_a": "QA engineer",
      "i_want": "to perform a data validation check ensuring 100% record parity",
      "so_that": "we can confidently switch production traffic to MongoDB without data errors",
      "acceptance_criteria": [
        {"given": "the migrated dataset in MongoDB", "when": "the validation script is executed", "then": "every customer record matches PostgreSQL source data exactly"}
      ],
      "priority": "High",
      "story_points": 5,
      "labels": ["data-validation", "quality-assurance", "cutover"]
    },
    {
      "id": "US-005",
      "title": "Configure MongoDB indexes to optimize read performance under 50ms (p95)",
      "as_a": "database administrator",
      "i_want": "to design and set up indexes in MongoDB collections",
      "so_that": "read operations perform efficiently and meet performance SLAs",
      "acceptance_criteria": [
        {"given": "defined MongoDB collections", "when": "indexes are created", "then": "read latency remains below 50ms p95"}
      ],
      "priority": "Medium",
      "story_points": 3,
      "labels": ["indexing", "performance", "mongodb"]
    },
    {
      "id": "US-006",
      "title": "Implement feature flag-driven rollout strategy for gradual migration activation",
      "as_a": "release manager",
      "i_want": "to enable MongoDB usage progressively using feature flags",
      "so_that": "we can ensure zero downtime and controlled risk during migration",
      "acceptance_criteria": [
        {"given": "API endpoints connected to data layer", "when": "feature flag is toggled for MongoDB reads/writes", "then": "traffic is routed accordingly without service interruption"}
      ],
      "priority": "Medium",
      "story_points": 5,
      "labels": ["feature-flags", "rollout", "zero-downtime"]
    },
    {
      "id": "US-007",
      "title": "Develop rollback mechanism to switch back to PostgreSQL within one hour",
      "as_a": "system engineer",
      "i_want": "to automate rollback procedures to revert data operations to PostgreSQL if issues occur",
      "so_that": "we can recover from failure rapidly and maintain service continuity",
      "acceptance_criteria": [
        {"given": "MongoDB active traffic", "when": "rollback is triggered", "then": "system routes writes and reads back to PostgreSQL within one hour and maintains consistency"}
      ],
      "priority": "High",
      "story_points": 8,
      "labels": ["rollback", "resilience", "safety"]
    }
  ]
}

{
  "architecture_overview": "The migration architecture uses a hybrid setup where PostgreSQL continues to serve production traffic while MongoDB is gradually introduced via a dual-write system and feature flag control. The solution includes a CDC-based backfill process that ensures all updates to customer data are streamed from PostgreSQL to MongoDB in real-time using Debezium or AWS DMS. Both databases will operate in parallel for a defined transition phase. MongoDB’s flexible document model will store customer profiles with nested country-specific fields, enabling future schema extensions without migrations. The system includes automated validation to check for data parity pre-cutover and rollback procedures to return to PostgreSQL within one hour if needed. All components will be containerized, monitored, and orchestrated using AWS DevOps services.",
  "technology_stack": ["Node.js", "Express", "PostgreSQL", "MongoDB Atlas", "AWS DMS or Debezium", "LaunchDarkly", "Docker", "AWS ECS", "Jest"],
  "api_endpoints": [
    {
      "method": "GET",
      "path": "/api/customers/:id",
      "description": "Fetch a customer profile. During migration, reads are routed based on feature flags, defaulting to PostgreSQL until MongoDB activation.",
      "request_body": "N/A",
      "response": "{ id: string, name: string, country: string, fields: { country_specific: {...} } }"
    },
    {
      "method": "POST",
      "path": "/api/customers",
      "description": "Create or update a customer profile. Dual-write mechanism sends payload to both PostgreSQL and MongoDB during migration.",
      "request_body": "{ name: string, country: string, fields: { country_specific: {...} } }",
      "response": "{ id: string, status: string }"
    },
    {
      "method": "GET",
      "path": "/api/migration/validate",
      "description": "Trigger a validation script comparing PostgreSQL and MongoDB records for parity verification before final cutover.",
      "request_body": "N/A",
      "response": "{ total_records_compared: number, mismatches_found: number, status: string }"
    },
    {
      "method": "POST",
      "path": "/api/migration/rollback",
      "description": "Trigger rollback process to route all traffic back to PostgreSQL within one hour if migration issues occur.",
      "request_body": "{ reason: string }",
      "response": "{ status: string, message: string }"
    }
  ],
  "database_schema": {
    "postgresql": "CREATE TABLE customers (id UUID PRIMARY KEY, name VARCHAR(255), country VARCHAR(64), ... existing fixed columns ...);",
    "mongodb": "db.customers.insertOne({ _id: UUID, name: 'John Doe', country: 'JP', fields: { national_id: 'MyNumber123456', vat_id: null, preferences: {...} }, updated_at: ISODate() });"
  },
  "security_considerations": [
    "Use AWS Secrets Manager for secure credential storage",
    "Enable TLS encryption between PostgreSQL, MongoDB, and application services",
    "Apply role-based access controls in MongoDB Atlas (read/write separation)",
    "Validate incoming data structure using JSON schema validation before dual-write operations",
    "Log all CDC operations and validation results in an auditable trail for compliance",
    "Ensure feature flag system access is limited to authorized release managers"
  ],
  "code_structure": {
    "backend": {
      "src": {
        "controllers": ["customerController.js", "migrationController.js"],
        "services": ["postgresService.js", "mongoService.js", "dualWriteService.js", "cdcService.js", "validationService.js", "rollbackService.js"],
        "utils": ["logger.js", "featureFlag.js", "schemaValidator.js"],
        "models": ["customerModelPostgres.js", "customerModelMongo.js"],
        "config": ["dbConfig.js", "featureFlagsConfig.js"]
      },
      "tests": ["unit/", "integration/", "parity/"]
    },
    "migration": {
      "cdc": ["debeziumConfig.json", "cdcListener.js"],
      "scripts": ["validateParity.js", "rollback.js", "indexSetup.js"]
    },
    "deployment": {
      "docker": ["Dockerfile", "docker-compose.yml"],
      "aws": ["ecsTaskDef.json", "cloudwatchAlerts.json"]
    }
  },
  "implementation_notes": "Use Debezium connector for PostgreSQL CDC streaming to handle initial backfill followed by live sync. Dual-write implemented at the service layer and controlled by LaunchDarkly feature flags. MongoDB indexes to include compound index on {'country': 1, 'name': 1} and country-specific subfield indexes for efficient querying. A data validation script will perform checksum comparisons between PostgreSQL and MongoDB datasets for parity assurance. Rollback mechanism involves toggling feature flag and reverting writeDriver settings. Automate all data migration steps and monitoring using AWS CloudWatch and ECS scheduled tasks. Follow zero-downtime deployment strategy with blue-green API servers to control traffic routing."
}

{
  "summary": "Implemented Node.js service for PostgreSQL to MongoDB migration supporting dual-write, CDC synchronization, validation parity checks, and rollback control using feature flags. It ensures zero downtime, data integrity, and backward-compatible API endpoints.",
  "code_files": [
    {
      "filename": "src/controllers/customerController.js",
      "language": "javascript",
      "description": "Controller handling customer profile CRUD and feature-flagged dual-write operations between PostgreSQL and MongoDB.",
      "code": "import express from 'express';
import { getCustomer, createOrUpdateCustomer } from '../services/dualWriteService.js';
import { featureFlag } from '../utils/featureFlag.js';
import { logger } from '../utils/logger.js';
const router = express.Router();

router.get('/:id', async (req, res) => {
  try {
    const readFromMongo = featureFlag.isEnabled('read_from_mongo');
    const customer = await getCustomer(req.params.id, readFromMongo);
    res.json(customer);
  } catch (err) {
    logger.error('Error fetching customer', err);
    res.status(500).json({ message: 'Internal Server Error' });
  }
});

router.post('/', async (req, res) => {
  try {
    const result = await createOrUpdateCustomer(req.body);
    res.json(result);
  } catch (err) {
    logger.error('Error creating/updating customer', err);
    res.status(500).json({ message: 'Internal Server Error' });
  }
});

export default router;"
    },
    {
      "filename": "src/controllers/migrationController.js",
      "language": "javascript",
      "description": "Controller handling migration validation and rollback endpoints.",
      "code": "import express from 'express';
import { validateParity } from '../services/validationService.js';
import { rollbackToPostgres } from '../services/rollbackService.js';
import { logger } from '../utils/logger.js';
const router = express.Router();

router.get('/validate', async (req, res) => {
  try {
    const result = await validateParity();
    res.json(result);
  } catch (err) {
    logger.error('Validation error', err);
    res.status(500).json({ message: 'Internal Server Error' });
  }
});

router.post('/rollback', async (req, res) => {
  try {
    const response = await rollbackToPostgres(req.body.reason);
    res.json(response);
  } catch (err) {
    logger.error('Rollback error', err);
    res.status(500).json({ message: 'Internal Server Error' });
  }
});

export default router;"
    },
    {
      "filename": "src/services/dualWriteService.js",
      "language": "javascript",
      "description": "Service implementing dual-write logic to both PostgreSQL and MongoDB during transitional phase.",
      "code": "import { postgresService } from './postgresService.js';
import { mongoService } from './mongoService.js';
import { featureFlag } from '../utils/featureFlag.js';
import { logger } from '../utils/logger.js';
import { validateSchema } from '../utils/schemaValidator.js';

export async function getCustomer(id, readFromMongo = false) {
  return readFromMongo ? await mongoService.getCustomerById(id) : await postgresService.getCustomerById(id);
}

export async function createOrUpdateCustomer(data) {
  validateSchema(data);
  const dualWriteEnabled = featureFlag.isEnabled('dual_write');
  const pgResult = await postgresService.upsertCustomer(data);
  if (dualWriteEnabled) {
    try {
      await mongoService.upsertCustomer(data);
    } catch (err) {
      logger.error('Mongo dual-write failed', err);
    }
  }
  return { id: pgResult.id, status: 'success' };
}"
    },
    {
      "filename": "src/services/validationService.js",
      "language": "javascript",
      "description": "Service performing Parity Validation between PostgreSQL and MongoDB datasets.",
      "code": "import { postgresService } from './postgresService.js';
import { mongoService } from './mongoService.js';
import { logger } from '../utils/logger.js';

export async function validateParity() {
  let mismatches = 0;
  const postgresRecords = await postgresService.getAllCustomers();
  for (let record of postgresRecords) {
    const mongoRecord = await mongoService.getCustomerById(record.id);
    if (!mongoRecord || JSON.stringify(mongoRecord) !== JSON.stringify(record)) {
      mismatches++;
    }
  }
  const status = mismatches === 0 ? 'success' : 'mismatch_found';
  logger.info(`Validation completed: ${mismatches} mismatches`);
  return { total_records_compared: postgresRecords.length, mismatches_found: mismatches, status };
}"
    },
    {
      "filename": "src/services/rollbackService.js",
      "language": "javascript",
      "description": "Service handling rollback to PostgreSQL using feature flag toggling.",
      "code": "import { featureFlag } from '../utils/featureFlag.js';
import { logger } from '../utils/logger.js';

export async function rollbackToPostgres(reason) {
  try {
    featureFlag.disable('read_from_mongo');
    featureFlag.disable('dual_write');
    logger.warn(`Rollback initiated: ${reason}`);
    return { status: 'success', message: 'Traffic reverted to PostgreSQL within one hour' };
  } catch (err) {
    logger.error('Rollback failed', err);
    return { status: 'error', message: 'Rollback process encountered an error' };
  }
}"
    },
    {
      "filename": "src/utils/featureFlag.js",
      "language": "javascript",
      "description": "Utility wrapper for LaunchDarkly feature flag controls.",
      "code": "import LaunchDarkly from 'launchdarkly-node-server-sdk';
import { logger } from './logger.js';
const ldClient = LaunchDarkly.init(process.env.LAUNCHDARKLY_SDK_KEY);
await ldClient.waitForInitialization();

export const featureFlag = {
  async isEnabled(flagName) {
    try {
      return await ldClient.variation(flagName, { key: 'system' }, false);
    } catch (err) {
      logger.error('Feature flag error', err);
      return false;
    }
  },
  disable(flagName) {
    logger.warn(`Feature flag ${flagName} should be disabled manually via dashboard.`);
  }
};"
    },
    {
      "filename": "src/services/mongoService.js",
      "language": "javascript",
      "description": "Service providing MongoDB customer operations.",
      "code": "import { MongoClient } from 'mongodb';
import { logger } from '../utils/logger.js';
const client = new MongoClient(process.env.MONGODB_URI);
await client.connect();
const db = client.db('customers_db');
const collection = db.collection('customers');

export const mongoService = {
  async getCustomerById(id) {
    return await collection.findOne({ _id: id });
  },
  async upsertCustomer(data) {
    await collection.updateOne({ _id: data.id }, { $set: data }, { upsert: true });
  },
  async getAllCustomers() {
    return await collection.find({}).toArray();
  }
};"
    },
    {
      "filename": "src/services/postgresService.js",
      "language": "javascript",
      "description": "Service providing PostgreSQL customer operations using pg library.",
      "code": "import pkg from 'pg';
import { logger } from '../utils/logger.js';
const { Pool } = pkg;
const pool = new Pool({ connectionString: process.env.DATABASE_URL });

export const postgresService = {
  async getCustomerById(id) {
    const res = await pool.query('SELECT * FROM customers WHERE id = $1', [id]);
    return res.rows[0];
  },
  async upsertCustomer(data) {
    const res = await pool.query('INSERT INTO customers (id, name, country) VALUES ($1, $2, $3) ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, country = EXCLUDED.country RETURNING id', [data.id, data.name, data.country]);
    return res.rows[0];
  },
  async getAllCustomers() {
    const res = await pool.query('SELECT * FROM customers');
    return res.rows;
  }
};"
    },
    {
      "filename": "src/utils/logger.js",
      "language": "javascript",
      "description": "Centralized logger utility for consistent audit trail and error handling.",
      "code": "import winston from 'winston';
export const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [new winston.transports.Console()]
});"
    },
    {
      "filename": "src/utils/schemaValidator.js",
      "language": "javascript",
      "description": "Utility for validating incoming customer data against JSON schema before writing.",
      "code": "import Ajv from 'ajv';
const ajv = new Ajv();
const schema = {
  type: 'object',
  properties: {
    id: { type: 'string' },
    name: { type: 'string' },
    country: { type: 'string' },
    fields: { type: 'object' }
  },
  required: ['name', 'country']
};
const validate = ajv.compile(schema);
export function validateSchema(data) {
  if (!validate(data)) throw new Error('Invalid customer schema');
}"
    }
  ],
  "setup_instructions": ["npm install", "npm run dev"],
  "environment_variables": [
    {
      "name": "DATABASE_URL",
      "description": "PostgreSQL connection string",
      "example": "postgresql://user:pass@localhost:5432/db"
    },
    {
      "name": "MONGODB_URI",
      "description": "MongoDB Atlas connection URI",
      "example": "mongodb+srv://user:pass@cluster.mongodb.net/customers_db"
    },
    {
      "name": "LAUNCHDARKLY_SDK_KEY",
      "description": "LaunchDarkly SDK key for feature flag control",
      "example": "sdk-123abc-key"
    }
  ],
  "dependencies": [
    {
      "name": "express",
      "version": "^4.18.2",
      "purpose": "Web framework for API endpoints"
    },
    {
      "name": "pg",
      "version": "^8.11.1",
      "purpose": "PostgreSQL driver and query execution"
    },
    {
      "name": "mongodb",
      "version": "^6.0.0",
      "purpose": "MongoDB driver for data access"
    },
    {
      "name": "launchdarkly-node-server-sdk",
      "version": "^7.0.1",
      "purpose": "Feature flag management for migration rollout control"
    },
    {
      "name": "winston",
      "version": "^3.8.2",
      "purpose": "Logging and monitoring utility"
    },
    {
      "name": "ajv",
      "version": "^8.12.0",
      "purpose": "JSON schema validation for input data integrity"
    }
  ]
}
